import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

const outcomeOfSync = (call: () => unknown): string => {
  try {
    call();
    return 'returned without throwing';
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
};

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration naming the tool when a static inputSchema is invalid JSON Schema', () => {
    const registry = new ToolRegistry();
    const message = outcomeOfSync(() =>
      registry.register(
        {
          name: 'bad_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {type: 'not_a_json_schema_type'},
        },
        async () => 'unreachable'
      )
    );

    expect({
      mentionsTool: message.includes('bad_schema_tool'),
      mentionsSchema: /schema/i.test(message),
    }).toEqual({
      mentionsTool: true,
      mentionsSchema: true,
    });
  });

  it('compiles a static tool inputSchema once at registration across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const rawSchema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const definition: ToolDefinition = {
      name: 'get_weather',
      description: 'Get the current weather for a location.',
      get inputSchema() {
        schemaReads += 1;
        return rawSchema;
      },
    };

    registry.register(definition, async input => String(input.location));
    const readsAtRegister = schemaReads;

    for (let i = 0; i < 10; i++) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect({readsAtRegister, readsAfterTenExecutes: schemaReads}).toEqual({
      readsAtRegister: 1,
      readsAfterTenExecutes: 1,
    });
  });

  it('resolves a function-valued tool definition per call and caches compiled validators by schema reference', async () => {
    const registry = new ToolRegistry();
    let schemaAReads = 0;
    let schemaBReads = 0;
    const schemaA: Record<string, unknown> = {
      type: 'object',
      get properties() {
        schemaAReads += 1;
        return {city: {type: 'string'}};
      },
      required: ['city'],
    };
    const schemaB: Record<string, unknown> = {
      type: 'object',
      get properties() {
        schemaBReads += 1;
        return {zipCode: {type: 'string'}};
      },
      required: ['zipCode'],
    };

    let activeSchema = schemaA;
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Switches schema dynamically',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const readsAtRegister = schemaAReads + schemaBReads;
    await registry.execute('dynamic_lookup', {city: 'Berlin'});
    const readsAfterFirstA = schemaAReads;
    await registry.execute('dynamic_lookup', {city: 'Paris'});

    activeSchema = schemaB;
    await registry.execute('dynamic_lookup', {zipCode: '10115'});
    const readsAfterFirstB = schemaBReads;
    const rejectedOldSchema = await registry.execute('dynamic_lookup', {city: 'Paris'});
    await registry.execute('dynamic_lookup', {zipCode: '75001'});

    expect({
      readsAtRegister,
      schemaACompiledOnce: readsAfterFirstA > 0 && schemaAReads === readsAfterFirstA,
      schemaBCompiledOnce: readsAfterFirstB > 0 && schemaBReads === readsAfterFirstB,
      rejectedAgainstCurrentSchema:
        rejectedOldSchema.result.includes('zipCode') && /required/i.test(rejectedOldSchema.result),
    }).toEqual({
      readsAtRegister: 0,
      schemaACompiledOnce: true,
      schemaBCompiledOnce: true,
      rejectedAgainstCurrentSchema: true,
    });
  });

  it('returns a rejection ToolResponse naming missing required properties and does not invoke the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get the current weather for a location.',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsLocation: response.result.includes('location'),
      mentionsRequired: /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsLocation: true,
      mentionsRequired: true,
    });
  });

  it('rejects a wrong-typed field naming the field path and expected type without including the offending value in result or logs', async () => {
    const loggedLines: string[] = [];
    const recordLog = (category: string, message: string, fields?: Record<string, unknown>) => {
      loggedLines.push(JSON.stringify({category, message, fields}));
    };
    const testLogger: Logger = {
      debug: recordLog,
      info: recordLog,
      warn: recordLog,
      error: recordLog,
    };
    setLogger(testLogger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_patient',
        description: 'Look up a patient record.',
        inputSchema: {
          type: 'object',
          properties: {patientId: {type: 'string'}},
          required: ['patientId'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('lookup_patient', {patientId: 987654321});

    expect({
      executorCalls,
      mentionsField: response.result.includes('patientId'),
      mentionsExpectedType: response.result.includes('string'),
      resultContainsValue: response.result.includes('987654321'),
      logsContainValue: loggedLines.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      resultContainsValue: false,
      logsContainValue: false,
    });
  });

  it('passes valid input including unlisted extra properties through to the executor unchanged once', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get the current weather for a location.',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string', default: 'London'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Berlin', traceId: 'req-42'});

    expect({response, receivedInputs}).toEqual({
      response: {result: 'ok'},
      receivedInputs: [{location: 'Berlin', traceId: 'req-42'}],
    });
  });
});

